 let docs=[];
 try{const response=await fetch(CATALOG_CONFIG.url+'/rest/v1/rpc/au_catalog_read',{method:'POST',headers:{apikey:CATALOG_CONFIG.key,'Content-Type':'application/json'},body:'{}',signal:AbortSignal.timeout(5000)});if(!response.ok)throw Error();docs=await response.json();if(!Array.isArray(docs))throw Error();try{localStorage.setItem('au-public-catalog',JSON.stringify(docs));}catch{}}
 catch{try{docs=JSON.parse(localStorage.getItem('au-public-catalog')||'[]');}catch{} }
 if(!Array.isArray(docs))return;
 for(const doc of docs){if(!doc||!Number.isInteger(doc.number)||typeof doc.title!=='string'||!Array.isArray(doc.tracks))continue;const i=COLLECTION.findIndex(v=>v.number===doc.number),volume=catalogMerge(doc);if(!volume.cover)continue;if(i<0)COLLECTION.push(volume);else COLLECTION[i]=volume;}
