function initMobileViewport(){
 let frame=0;const viewport=window.visualViewport;
 function apply(){frame=0;const root=document.documentElement;root.style.setProperty('--au-vw',(viewport?.width||window.innerWidth)+'px');root.style.setProperty('--au-vh',(viewport?.height||window.innerHeight)+'px');root.style.setProperty('--au-vx',(viewport?.offsetLeft||0)+'px');root.style.setProperty('--au-vy',(viewport?.offsetTop||0)+'px');if(!matchMedia('(max-width:700px), (max-height:500px) and (max-width:1000px)').matches)return;const focused=document.activeElement;if(focused?.closest('dialog[open]')&&/^(INPUT|TEXTAREA|SELECT)$/.test(focused.tagName)){const rect=focused.getBoundingClientRect(),top=viewport?.offsetTop||0,bottom=top+(viewport?.height||innerHeight);if(rect.top<top+56||rect.bottom>bottom-12)focused.scrollIntoView({block:'nearest',inline:'nearest'});}}
 const schedule=()=>{if(!frame)frame=requestAnimationFrame(apply);};window.addEventListener('resize',schedule);viewport?.addEventListener('resize',schedule);viewport?.addEventListener('scroll',schedule);
 const observer=new MutationObserver(changes=>{for(const change of changes){if(change.target.tagName==='DIALOG'&&change.target.open){change.target.scrollTop=0;schedule();}}});observer.observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});apply();
}

