function canvasFor(volume, width=440) {const c=element('canvas');c.width=c.height=width;c.setAttribute('role','img');c.setAttribute('aria-label','Pochette — '+volume.title);drawCover(c,volume);return c;}
async function decodeCover(source) {
 if(coverCache.has(source))return coverCache.get(source);
 const promise=(async()=>{
  let url, temporary=false;
  if(source && typeof source==='object') {
   const values=source.data.flat();
   if(values.length!==source.byteLength||!values.every(n=>Number.isInteger(n)&&n>=0&&n<=255))throw new Error('Données de pochette modifiées pendant la copie');
   const bytes=Uint8Array.from(values);
   if(bytes.reduce((sum,n)=>(sum+n)>>>0,0)!==source.checksum)throw new Error('Données de pochette incomplètes');
   const blob=new Blob([bytes],{type:source.mime});
   if(typeof createImageBitmap==='function') {try {return await createImageBitmap(blob);}catch{}}
   url=URL.createObjectURL(blob);temporary=true;
  } else {url=new URL(source,document.baseURI);const local=typeof source==='string'&&source.startsWith('./cover-')&&url.origin===location.origin;if(url.protocol!=='https:'&&!local&&!/^data:image\/(webp|png|jpeg);base64,/.test(source))throw new Error('URL de pochette invalide');url=url.href;}
  return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{if(temporary)URL.revokeObjectURL(url);resolve(image);};image.onerror=()=>{if(temporary)URL.revokeObjectURL(url);reject(new Error('Pochette inaccessible'));};image.src=url;});
 })();
 coverCache.set(source,promise);promise.catch(()=>coverCache.delete(source));return promise;
}
async function drawCover(canvas, volume) {
 const request={};coverRequests.set(canvas,request);canvas.dataset.coverState='loading';
 const context=canvas.getContext('2d');context.clearRect(0,0,canvas.width,canvas.height);
 try {const bitmap=await decodeCover(volume.cover);if(coverRequests.get(canvas)!==request)return;context.imageSmoothingEnabled=true;context.imageSmoothingQuality='high';context.drawImage(bitmap,0,0,canvas.width,canvas.height);canvas.dataset.coverState='ready';motionCovers.attach(canvas,volume);}
 catch(error) {if(coverRequests.get(canvas)!==request)return;context.fillStyle='#271336';context.fillRect(0,0,canvas.width,canvas.height);context.fillStyle='#ff9bcf';context.font=Math.max(10,canvas.width/18)+'px Arial';context.textAlign='center';context.fillText('Pochette indisponible',canvas.width/2,canvas.height/2);canvas.dataset.coverState='error';canvas.dataset.coverError=error.message;}
}
