function clock(value) {if(!Number.isFinite(value)||value<0)return '0:00';return Math.floor(value/60)+':'+number(Math.floor(value%60));}
function status(text, error=false) {$('status').textContent=text;$('retry').hidden=!error;}
function timeline() {
 const duration=Number.isFinite(audio.duration)&&audio.duration>0?audio.duration:0;
 $('seek').disabled=!duration;$('seek').max=duration||100;
 if(!seeking)$('seek').value=duration?audio.currentTime:0;
 $('elapsed').textContent=clock(seeking?Number($('seek').value):audio.currentTime);$('duration').textContent=clock(duration);
 $('seek').setAttribute('aria-valuetext',clock(Number($('seek').value))+' sur '+clock(duration));
}
function updatePlayback() {
 const on=playing(),current=track();
 $('play').disabled=!current||!mediaURL(current.src);$('play').setAttribute('aria-label',on?'Mettre en pause':'Lire');
 $('playIcon').setAttribute('d',on?'M6 4h4v16H6zm8 0h4v16h-4z':'M8 4v16l13-8z');
 $('previous').disabled=!current;$('next').disabled=!current;
 $('albumPlay').textContent=selectedVolume===playingVolume&&on?'Mettre en pause Ⅱ':'Écouter le volume ▶';
 document.querySelectorAll('.track').forEach(b=>{
  const i=Number(b.dataset.track),active=selectedVolume===playingVolume&&i===playingTrack;
  b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');
  b.querySelector('.track-state').textContent=active?(on?'En lecture':'Prête'):'Écouter';
  b.setAttribute('aria-label',(active&&on?'Mettre en pause':'Écouter')+' la piste '+COLLECTION[selectedVolume].tracks[i].position+' : '+COLLECTION[selectedVolume].tracks[i].title);
 });
}
