let syncTrackLock=null;
function selectTrack(vi,ti,autoplay=false,preserveQueue=false) {
 window.dispatchEvent(new Event('au:before-trackchange'));
 if(syncTrackLock&&syncTrackLock!==COLLECTION[vi]?.number+':'+COLLECTION[vi]?.tracks[ti]?.number){status('Termine ou quitte la synchronisation avant de changer de morceau.');return;}
 const t=COLLECTION[vi]?.tracks[ti];if(!t)return;
 if(!preserveQueue)window.AU_PERSONAL?.clearQueue();
 ++playRequest;audio.pause();playingVolume=vi;playingTrack=ti;seeking=false;
 const url=mediaURL(t.src);if(url)audio.src=url;else audio.removeAttribute('src');
 audio.load();updateNow();status(url?'Prêt à écouter.':'Ce morceau n’est pas encore disponible.');
 window.dispatchEvent(new CustomEvent('au:trackchange',{detail:{volume:vi,track:ti}}));
 if(autoplay&&url)startPlayback();
}
async function startPlayback() {
 const t=track(),url=t&&mediaURL(t.src);if(!url){status('Ce morceau n’est pas encore disponible.');return;}
 const request=++playRequest;
 if(audio.src!==url||audio.error){audio.src=url;audio.load();}
 if(audio.ended)audio.currentTime=0;
 status('Chargement du morceau…');
 try {await audio.play();if(request!==playRequest)return;status('Lecture en cours.');}
 catch(e) {if(request!==playRequest||e.name==='AbortError')return;status(e.name==='NotAllowedError'?'Appuie sur Lecture pour lancer le morceau.':'Le morceau n’a pas pu être chargé. Réessaie dans un instant.',e.name!=='NotAllowedError');}
 updatePlayback();
}
function togglePlay() {if(audio.paused)startPlayback();else{++playRequest;audio.pause();status('Lecture en pause.');}}
function move(direction,autoplay=playing()) {
 if(syncTrackLock){status('Morceau verrouillé pendant la synchronisation.');return;}
 if(window.AU_PERSONAL?.move(direction,autoplay))return;
 const tracks=COLLECTION[playingVolume].tracks,valid=tracks.map((t,i)=>mediaURL(t.src)?i:-1).filter(i=>i>=0);if(!valid.length)return;
 let target;
 if(shuffle&&direction>0&&valid.length>1){const others=valid.filter(i=>i!==playingTrack);target=others[Math.floor(Math.random()*others.length)];}
 else target=valid[(valid.indexOf(playingTrack)+direction+valid.length)%valid.length];
 selectTrack(playingVolume,target,autoplay);
}
$('play').addEventListener('click',togglePlay);$('previous').addEventListener('click',()=>move(-1));$('next').addEventListener('click',()=>move(1));$('retry').addEventListener('click',startPlayback);
