$('repeat').addEventListener('click',()=>{repeat=!repeat;$('repeat').setAttribute('aria-pressed',String(repeat));status(repeat?'Répétition de la sélection activée.':'Répétition désactivée.');});
$('seek').addEventListener('input',()=>{seeking=true;timeline();});
$('seek').addEventListener('change',()=>{if(Number.isFinite(audio.duration))audio.currentTime=Math.max(0,Math.min(audio.duration,Number($('seek').value)));seeking=false;timeline();});
audio.volume=Number($('volume').value);
$('volume').addEventListener('input',()=>{audio.volume=Number($('volume').value);audio.muted=false;});
$('mute').addEventListener('click',()=>{audio.muted=!audio.muted;});
audio.addEventListener('volumechange',()=>{$('volume').value=audio.muted?0:audio.volume;$('mute').setAttribute('aria-pressed',String(audio.muted||audio.volume===0));$('mute').setAttribute('aria-label',audio.muted?'Rétablir le son':'Couper le son');});
['loadedmetadata','durationchange','timeupdate'].forEach(e=>audio.addEventListener(e,timeline));
