audio.addEventListener('waiting',()=>{if(!audio.paused)status('Chargement du morceau…');});
audio.addEventListener('error',()=>{if(audio.error&&audio.getAttribute('src')){status('Le morceau est momentanément inaccessible. Tu peux réessayer.',true);updatePlayback();}});
audio.addEventListener('ended',()=>{if(syncTrackLock){audio.pause();updatePlayback();status('Fin du morceau. Reviens à 00:00 pour continuer la synchronisation.');window.dispatchEvent(new Event('au:sync-audio-ended'));return;}if(window.AU_PERSONAL?.move(1,true,true))return;const remaining=COLLECTION[playingVolume].tracks.findIndex((t,i)=>i>playingTrack&&mediaURL(t.src));if(shuffle||repeat)move(1,true);else if(remaining!==-1)selectTrack(playingVolume,remaining,true);else{status('Fin du volume. Choisis un autre morceau.');updatePlayback();}});

