window.addEventListener('au:lyrics-selection',event=>{if(!community.song)return;const s=event.detail?.selection;if(!s||typeof s.quote!=='string'||!s.quote.trim())return;if(s.quote.length>240||s.end_word-s.start_word>=48){communityNotice('Le texte reste sélectionnable. Pour une explication, choisis un passage de 240 caractères maximum.');return;}if(!Number.isInteger(s.start_word)||!Number.isInteger(s.end_word)||s.start_word<0||s.end_word<s.start_word)return;community.selection=s;$('explainPassage').disabled=false;communityNotice('Passage sélectionné : « '+s.quote+' »');if(event.detail.open)openAnnotationDialog(s);});
