$('annotationForm').addEventListener('submit',async e=>{e.preventDefault();const selection=community.selection;if(!community.song||!selection)return;const author=$('annotationAuthor').value.trim(),body=$('annotationBody').value.trim();if(author.length<2||body.length<10){$('annotationFeedback').textContent='Ajoute un pseudo et une explication d’au moins 10 caractères.';return;}const version=community.version,song=community.song,submit=$('publishAnnotation');submit.disabled=true;$('annotationFeedback').textContent='Publication…';try{await communityRPC('au_add_annotation',{p_token:visitorToken(),p_song_key:song,p_start_word:selection.start_word,p_end_word:selection.end_word,p_quote:selection.quote,p_author_name:author,p_body:body});window.dispatchEvent(new CustomEvent('au:activity',{detail:{kind:'function',details:{function:'annotation',trackKey:song}}}));localWrite('au-community-name',author);if(version===community.version){$('annotationBody').value='';$('annotationFeedback').textContent='Ton explication est publiée !';community.version++;community.loading=false;await loadCommunity();}}catch(error){if(version===community.version)$('annotationFeedback').textContent=error.message;}finally{submit.disabled=false;}});

