// Conservative, line-only structure filtering. Original catalog text is retained.
const AU_LYRICS=(()=>{
 const section=/^(?:couplet|refrain|intro|outro|pont|pr[ée][ -]?refrain|post[ -]?refrain|interlude|instrumental(?:e)?|verse|chorus|pre[ -]?chorus|post[ -]?chorus|bridge|hook|break|solo)(?:\s+(?:[0-9]+|[IVX]+))?(?:\s*[x×]\s*[0-9]+)?(?:\s*[:—–-]\s*[^\[\]\r\n]+)?$/iu;
 function annotation(line){const s=String(line).trim(),wrapped=/^[\[(].*[\])]$/.test(s),value=s.replace(/^[\[(]|[\])]$/g,'').replace(/\s*:\s*$/,'').trim();return section.test(value)||/^(?:feat\.?|featuring|avec)\s*[:—–-]?\s+[^\n]{1,100}$/iu.test(value)&&(wrapped||/:$/.test(s)||/^feat\.?/i.test(s));}
 function lines(text){return String(text||'').replace(/\r\n?/g,'\n').split('\n').map(s=>s.trim()).filter(s=>s&&!annotation(s));}
 return {annotation,lines};
})();
