  if(post.mine){const remove=btn('Supprimer',async()=>{if(!window.confirm('Supprimer ta publication ?'))return;remove.disabled=true;try{const ok=await rpc('au_discovery_post_delete',{p_token:visitorToken(),p_post_id:post.id});if(!ok)throw new Error('Cette publication ne peut plus être supprimée.');await loadFeed(feed,false,true);}catch(e){feed.status.textContent=e.message;remove.disabled=false;}},'dc-text-button dc-delete');actions.append(remove);}
  if(actions.childElementCount)card.append(actions);return card;
