 function renderFeed(feed){feed.list.replaceChildren(...feed.items.map(post=>postCard(post,feed)));if(!feed.items.length)feed.list.append(note(({story:'Aucune histoire pour le moment. Partage un souvenir ou une référence.',archive:'Aucune recherche pour le moment. Quel morceau ou visuel manque à la collection ?',report:'Tu n’as envoyé aucun signalement depuis ce navigateur.'})[feed.kind]));feed.more.hidden=feed.items.length>=feed.total;}
