  const panel=el('section','dc-panel'),head=el('div','dc-heading');head.append(el('h2','',title));feed.refresh=btn('Actualiser',()=>loadFeed(feed),'dc-text-button');head.append(feed.refresh);panel.append(head,note(description),formFor(feed));
