 async function showPreview(){const doc=await collect();preview.replaceChildren(element('h3','','Aperçu avant publication'),canvasFor(catalogMerge(doc),400),element('h3','',doc.title),element('p','',doc.tracks.length+' morceaux · '+doc.tracks.filter(t=>t.genius?.id||t.lyrics?.trim()).length+' paroles intégrées'));const list=element('ol');for(const t of doc.tracks)list.append(element('li','',t.title+' — '+t.artist));preview.append(list);if(doc.tracks.length){const player=document.createElement('audio');player.controls=true;player.preload='none';player.src=doc.tracks[0].src;player.setAttribute('aria-label','Tester le premier morceau');preview.append(player);}preview.hidden=false;previewed=JSON.stringify(doc);publish.disabled=false;preview.scrollIntoView({block:'nearest',behavior:'smooth'});note('Vérifie la pochette et les titres ci-dessous. « Publier ce volume » appliquera ces changements pour tous les visiteurs.');}
