// An arrival notice in the page flow; dismissal lasts for this browser tab's session.
(()=>{
 const key='au-development-notice-v1';
 function mount(){
  if(document.getElementById('developmentNotice'))return;
  try{if(sessionStorage.getItem(key)==='dismissed')return;}catch{}
  const host=document.getElementById('pageScroll')||document.querySelector('main');
  if(!host)return;
  const notice=document.createElement('aside');
  notice.id='developmentNotice';notice.className='au-development-notice';
  notice.setAttribute('aria-labelledby','developmentNoticeTitle');
  const copy=document.createElement('div');
  const title=document.createElement('strong');title.id='developmentNoticeTitle';
  title.textContent='Le site est encore en développement';
  const message=document.createElement('p');
  message.textContent='Ce n’est pas une version finale : le site est encore loin d’être terminé. Certaines fonctions peuvent être incomplètes, instables ou ne pas fonctionner correctement. Un fonctionnement à 100 % n’est pas encore garanti.';
  const close=document.createElement('button');close.type='button';
  close.textContent='J’ai compris';close.setAttribute('aria-label','J’ai compris, masquer l’avertissement pour cette visite');
  close.addEventListener('click',()=>{
   try{sessionStorage.setItem(key,'dismissed');}catch{}
   // Keep keyboard focus in the content instead of dropping it onto the body.
   const heading=document.querySelector('section.page:not([hidden]) h1');
   notice.remove();
   if(heading){if(!heading.hasAttribute('tabindex'))heading.tabIndex=-1;heading.focus({preventScroll:true});}
  });
  copy.append(title,message);notice.append(copy,close);host.prepend(notice);
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();

