 const headerButton=button('au-account-button','Mon compte',()=>openAccount());headerButton.id='openAccount';document.querySelector('.topbar-inner').append(headerButton);
 const libraryPanel=element('div','au-library-account'),libraryText=element('p','','Connecte-toi pour retrouver tes favoris et playlists sur tes appareils.');libraryText.id='accountLibraryStatus';libraryPanel.append(libraryText,button('button secondary','Mon compte',()=>openAccount()));document.querySelector('#bibliotheque .page-heading').after(libraryPanel);
 function openAccount(){if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
 function modeUI(next){const changed=mode!==next;mode=next;$('accountNameLabel').hidden=next!=='signup';$('accountName').required=next==='signup';$('accountPasswordLabel').hidden=next==='forgot';$('accountPassword').required=next!=='forgot';$('accountPassword').minLength=next==='signup'?12:1;$('accountPassword').autocomplete=next==='signup'?'new-password':'current-password';$('accountPasswordHint').hidden=next!=='signup';$('accountSubmit').textContent=next==='signup'?'Créer mon compte':next==='forgot'?'Recevoir le lien de récupération':'Se connecter';$('accountLoginTab').setAttribute('aria-pressed',String(next==='login'));$('accountSignupTab').setAttribute('aria-pressed',String(next==='signup'));$('accountResend').hidden=next!=='signup';if(changed)$('accountPassword').value='';}
 function stateUI(){$('accountGuest').hidden=!!user||recovery;$('accountMember').hidden=!user||recovery;$('accountRecovery').hidden=!recovery;headerButton.textContent=user?'Mon compte · connecté':'Mon compte';if(user){$('accountGreeting').textContent='Bonjour '+(user.user_metadata?.nickname||'à toi')+'.';$('accountEmailDisplay').textContent=user.email||'';}else{$('accountEmailDisplay').textContent='';$('accountGreeting').textContent='';}$('accountSubmit').disabled=loading;}
 function friendly(error){const code=error?.code||'',message=error?.message||'';if(code==='invalid_credentials')return 'E-mail ou mot de passe incorrect.';if(code==='email_not_confirmed')return 'Confirme ton adresse avec le lien reçu par e-mail avant de te connecter.';if(/rate|over_email|429/.test(code+message))return 'Trop de tentatives. Patiente quelques minutes avant de réessayer.';if(/weak_password/.test(code))return 'Choisis un mot de passe plus long et difficile à deviner.';if(/email_address_not_authorized|smtp|Email address not authorized/.test(code+message))return 'L’envoi des e-mails n’est pas encore disponible. Réessaie plus tard.';if(/expired|otp_expired|bad_code_verifier|flow_state/.test(code+message))return 'Ce lien a expiré ou a déjà été utilisé. Demande un nouveau lien.';if(/fetch|network/i.test(message))return 'Connexion impossible. Tes changements restent conservés sur cet appareil.';return 'Impossible de terminer cette action. Réessaie dans un instant.';}
 function cacheKey(id){return 'au-account-cache:'+id;}
 function readCache(id){try{return JSON.parse(localStorage.getItem(cacheKey(id)))||null;}catch{return null;}}
 function cache(){if(user)localWrite(cacheKey(user.id),JSON.stringify({library:window.AU_PERSONAL.snapshot(),revision,dirty}));}
 async function fetchLibrary(){const {data,error}=await client.rpc('au_account_library_get');if(error)throw error;return data;}
 function applyRemote(data){revision=Number(data.revision);dirty=false;conflict=null;$('accountConflict').hidden=true;window.AU_PERSONAL.useAccount(user.id,data.library);cache();notice('Favoris et playlists synchronisés avec ton compte.');}
 async function connect(session){const next=session?.user||null;if(next?.id===user?.id){user=next;stateUI();refreshCreator();return;}const generation=++epoch;clearTimeout(syncTimer);conflict=null;$('accountConflict').hidden=true;user=next;activity17.changed();statistics17.changed();dirty=false;revision=0;stateUI();refreshCreator();majorSocial.changed();activationSync.changed();moderationV12.changed();lyricsContributions.changed();repertoire.changed();if(!user){window.AU_PERSONAL.useAccount(null);notice('Mode sans compte : ta bibliothèque reste sur cet appareil.');return;}
  const id=user.id,cached=readCache(id);window.AU_PERSONAL.useAccount(id,cached?.library||{favorites:[],playlists:[]});revision=Number(cached?.revision)||0;dirty=!!cached?.dirty;notice('Chargement de ta bibliothèque…');
  try{const data=await fetchLibrary();if(generation!==epoch)return;if(dirty){if(revision!==Number(data.revision)){conflict=data;$('accountConflict').hidden=false;notice('Une autre version de ta bibliothèque existe. Ouvre Mon compte pour choisir.');}else await sync();}else applyRemote(data);}catch(e){if(generation===epoch)notice(friendly(e));}
 }
 async function sync(){if(!client||!user||conflict)return false;if(saving)return saving;if(!dirty){const generation=epoch;try{const data=await fetchLibrary();if(generation===epoch){if(dirty){if(Number(data.revision)!==revision){conflict=data;$('accountConflict').hidden=false;notice('Ta bibliothèque a changé sur un autre appareil.');return false;}return sync();}applyRemote(data);}return true;}catch(e){notice(friendly(e));return false;}}
  const generation=epoch,payload=window.AU_PERSONAL.snapshot(),sent=JSON.stringify(payload),rev=revision;notice('Enregistrement de ta bibliothèque…');
  saving=(async()=>{try{const {data,error}=await client.rpc('au_account_library_save',{p_library:payload,p_revision:rev});if(error)throw error;if(generation!==epoch)return false;if(data.conflict){conflict=data;$('accountConflict').hidden=false;notice('Ta bibliothèque a changé sur un autre appareil. Choisis la version à conserver.');return false;}revision=Number(data.revision);dirty=JSON.stringify(window.AU_PERSONAL.snapshot())!==sent;cache();notice(dirty?'Enregistrement des derniers changements…':'Favoris et playlists synchronisés avec ton compte.');return true;}catch(e){if(generation===epoch){cache();notice(friendly(e));}return false;}finally{saving=null;if(generation===epoch&&dirty&&!conflict){} }})();const ok=await saving;if(ok&&dirty&&!conflict)syncTimer=setTimeout(sync,600);return ok;
 }
 window.addEventListener('au:librarychange',()=>{if(!user)return;dirty=true;cache();clearTimeout(syncTimer);if(!conflict)syncTimer=setTimeout(sync,600);});
 $('accountClose').addEventListener('click',()=>dialog.close());$('accountLoginTab').addEventListener('click',()=>modeUI('login'));$('accountSignupTab').addEventListener('click',()=>modeUI('signup'));$('accountForgot').addEventListener('click',()=>modeUI('forgot'));
 $('accountForm').noValidate=true;
 function validateAccount(){const name=$('accountName'),email=$('accountEmail'),password=$('accountPassword');let field,message;if(mode==='signup'&&name.value.trim().length<2){field=name;message='Saisis un pseudo d’au moins 2 caractères.';}else if(!email.value.trim()||!email.validity.valid){field=email;message='Saisis une adresse e-mail valide.';}else if(mode!=='forgot'&&password.value.length<(mode==='signup'?12:1)){field=password;message=mode==='signup'?'Choisis un mot de passe d’au moins 12 caractères.':'Saisis ton mot de passe.';}if(message){notice(message);field.focus();return false;}return true;}
 $('accountForm').addEventListener('submit',async e=>{e.preventDefault();if(!validateAccount())return;if(!client){notice('Le service de compte se charge. Réessaie dans un instant.');return;}if(loading)return;loading=true;stateUI();notice('Connexion au service…');const email=$('accountEmail').value.trim(),password=$('accountPassword').value;const redirectTo=new URL('./',location.href).href;try{let result;if(mode==='signup'){result=await client.auth.signUp({email,password,options:{data:{nickname:$('accountName').value.trim()},emailRedirectTo:redirectTo}});if(result.error)throw result.error;$('accountPassword').value='';notice(result.data.session?'Compte créé. Chargement de ta bibliothèque…':'Si cette adresse peut être inscrite, tu recevras un e-mail. Ouvre son lien pour confirmer ton compte.');}else if(mode==='forgot'){result=await client.auth.resetPasswordForEmail(email,{redirectTo});if(result.error)throw result.error;notice('Si un compte correspond à cette adresse, tu recevras un lien pour choisir un nouveau mot de passe.');}else{result=await client.auth.signInWithPassword({email,password});if(result.error)throw result.error;$('accountPassword').value='';await connect(result.data.session);}}catch(error){notice(friendly(error));}finally{loading=false;stateUI();}});
 $('accountResend').addEventListener('click',async()=>{if(!client||!$('accountEmail').reportValidity())return;const b=$('accountResend');b.disabled=true;try{const {error}=await client.auth.resend({type:'signup',email:$('accountEmail').value.trim(),options:{emailRedirectTo:new URL('./',location.href).href}});if(error)throw error;notice('Si une confirmation est en attente, un nouvel e-mail sera envoyé.');}catch(e){notice(friendly(e));}finally{b.disabled=false;}});
 $('accountRecovery').addEventListener('submit',async e=>{e.preventDefault();if(!client)return;const password=$('accountNewPassword').value;if(password!==$('accountNewPasswordConfirm').value){notice('Les deux mots de passe doivent être identiques.');return;}const b=$('accountSavePassword');b.disabled=true;try{const {error}=await client.auth.updateUser({password});if(error)throw error;$('accountRecovery').reset();recovery=false;stateUI();notice('Ton mot de passe a été enregistré.');}catch(error){notice(friendly(error));}finally{b.disabled=false;}});
 $('accountSync').addEventListener('click',sync);$('accountUseRemote').addEventListener('click',()=>{if(conflict)applyRemote(conflict);});$('accountKeepLocal').addEventListener('click',()=>{if(!conflict)return;revision=Number(conflict.revision);conflict=null;$('accountConflict').hidden=true;dirty=true;cache();sync();});
