 async function boot(){try{await new Promise((resolve,reject)=>{if(window.supabase?.createClient){resolve();return;}const s=document.createElement('script');s.src='./supabase-auth-client.js';s.onload=resolve;s.onerror=reject;document.head.append(s);});client=window.supabase.createClient(COMMUNITY_CONFIG.url,COMMUNITY_CONFIG.key,{auth:{storageKey:'au-auth-session',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});client.auth.onAuthStateChange((event,session)=>{setTimeout(()=>{if(event==='PASSWORD_RECOVERY'){recovery=true;openAccount();}connect(session);},0);});const {data,error}=await client.auth.getSession();if(error)throw error;await connect(data.session);await trackSharing.ready();}catch(error){notice('Le service de compte est indisponible. Tu peux continuer à écouter sans compte.');await trackSharing.ready();}}

