let creatorPrincipal=null,creatorAccess=false,adminPage=0,adminKind='annotations',adminGeneration=0;
const creatorBadge=element('span','au-creator-badge','Créateur du site');creatorBadge.hidden=true;$('accountGreeting').after(creatorBadge);
const creatorEntry=button('button au-admin-entry','Administration du site',()=>{dialog.close();$('creatorDialog').showModal();loadAdmin();});creatorEntry.hidden=true;$('accountMember').append(creatorEntry);
