const adminHead=element('div','au-dialog-head');adminHead.append(element('h2','','Espace Créateur.'),button('au-icon','Fermer',()=>adminDialog.close()));
const adminHelp=element('p','au-note','Modération, signalements privés et statuts de soutien. Les avantages donateurs seront définis plus tard.');
const adminTabs=element('div','filters');const categories={annotations:'Explications',posts:'Communauté',reports:'Signalements',members:'Comptes'};
