const adminStatus=element('p','au-note');adminStatus.setAttribute('role','status');const adminItems=element('div','au-admin-items');const adminControls=element('div','actions');const adminPrev=button('button secondary','Précédent',()=>{adminPage=Math.max(0,adminPage-1);loadAdmin();});const adminNext=button('button secondary','Suivant',()=>{adminPage++;loadAdmin();});adminControls.append(adminPrev,adminNext,button('text-button','Actualiser',loadAdmin));adminDialog.append(adminHead,adminHelp,adminTabs,adminStatus,adminItems,adminControls);document.body.append(adminDialog);
