 window.AU_INIT_BLIND_TEST({getSongs:()=>COLLECTION.flatMap(v=>v.tracks.filter(t=>mediaURL(t.src)).map(t=>({key:v.number+':'+t.number,title:t.title,volume:v.number,volumeLabel:v.title||'Volume '+v.number,src:mediaURL(t.src)}))),navigate,mainAudio:audio,renderCover:song=>canvasFor(COLLECTION.find(v=>v.number===song.volume),240),renderVolumeLabel:song=>motionCovers.bindTitle(element('small','',song.volumeLabel),COLLECTION.find(v=>v.number===song.volume)),getHistory:async()=>{if(!user)return null;const owner=user.id;const {data,error}=await client.rpc('au_blind_history_17v01');if(error||user?.id!==owner)return null;return data;},record:activity17.record});
